('quick:sutton-hoo', $pvpbank${"id":"quick:sutton-hoo","type":"multiple-choice","version":"1:45df1852","categoryId":"history","subcategoryId":"quick-quiz","conceptIds":["quick:sutton-hoo"],"difficulty":"easy","difficultyOrigin":"editorial","prompt":"Τι είχαν θάψει κάτω από τον μεγάλο τύμβο του Σάτον Χου στην Αγγλία;","explanation":"Ο τύμβος κάλυπτε ένα αγγλοσαξονικό πλοίο. Μέσα του υπήρχε ταφικός θάλαμος με πολύτιμα αντικείμενα.","sources":[{"title":"Sutton Hoo","url":"https://www.nationaltrust.org.uk/visit/suffolk/sutton-hoo/digging-the-dirt-at-sutton-hoo-the-true-story-behind-the-dig","publisher":"National Trust"}],"content":{"answers":["Ένα άρμα","Ένα πλοίο","Μια γέφυρα","Ένα άγαλμα"],"correctIndex":1}}$pvpbank$::jsonb),
